"use strict";(self.webpackChunkdocs_scadys_io=self.webpackChunkdocs_scadys_io||[]).push([["6329"],{612(e,t,i){i.r(t),i.d(t,{metadata:()=>n,default:()=>h,frontMatter:()=>o,contentTitle:()=>r,toc:()=>c,assets:()=>l});var n=JSON.parse('{"id":"circuit-design/principles/dnp-isolation","title":"Isolating Circuit Blocks with DNP Parts","description":"A prototype carries every option the product might need, because a prototype that is built only in the expected configuration proves nothing about the alternatives. A DNP (do not populate) part is the tool that makes this cheap. Its land is on the board, but the part is not fitted, so a circuit can be connected or disconnected by fitting or removing one resistor.","source":"@site/engineering/circuit-design/principles/dnp-isolation.md","sourceDirName":"circuit-design/principles","slug":"/circuit-design/principles/dnp-isolation","permalink":"/engineering/circuit-design/principles/dnp-isolation","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"sidebar_position":3,"title":"Isolating Circuit Blocks with DNP Parts","sidebar_label":"DNP isolation"},"sidebar":"aboutSidebar","previous":{"title":"Test Points","permalink":"/engineering/circuit-design/principles/test-points"},"next":{"title":"Part sizes (0603 against 0402)","permalink":"/engineering/circuit-design/principles/part-sizes"}}'),a=i(4848),s=i(8453);let o={sidebar_position:3,title:"Isolating Circuit Blocks with DNP Parts",sidebar_label:"DNP isolation"},r="Isolating Circuit Blocks with DNP Parts",l={},c=[{value:"Fit the fallback circuit, isolate it with a link",id:"fit-the-fallback-circuit-isolate-it-with-a-link",level:2},{value:"Exactly one link in a select group",id:"exactly-one-link-in-a-select-group",level:2},{value:"A resistor in the select position measures current",id:"a-resistor-in-the-select-position-measures-current",level:2},{value:"Leave a land for a value not yet known",id:"leave-a-land-for-a-value-not-yet-known",level:2},{value:"Why this is planned in, not patched on",id:"why-this-is-planned-in-not-patched-on",level:2},{value:"Documenting DNP parts",id:"documenting-dnp-parts",level:2}];function d(e){let t={code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"isolating-circuit-blocks-with-dnp-parts",children:"Isolating Circuit Blocks with DNP Parts"})}),"\n",(0,a.jsx)(t.p,{children:"A prototype carries every option the product might need, because a prototype that is built only in the expected configuration proves nothing about the alternatives. A DNP (do not populate) part is the tool that makes this cheap. Its land is on the board, but the part is not fitted, so a circuit can be connected or disconnected by fitting or removing one resistor."}),"\n",(0,a.jsx)(t.h2,{id:"fit-the-fallback-circuit-isolate-it-with-a-link",children:"Fit the fallback circuit, isolate it with a link"}),"\n",(0,a.jsx)(t.p,{children:"Where a block has a fallback, the fallback's parts are fitted on the prototype, and a DNP 0 \u03A9 link disconnects its output. A fallback is then enabled by fitting one link on an assembled board, rather than by placing a regulator and its capacitors by hand on a board that is already built."}),"\n",(0,a.jsxs)(t.p,{children:["On the MDD500 prototype, the panel's 1.8 V IO rail normally comes from the processor's internal LDO. A separate 1.8 V regulator, ",(0,a.jsx)(t.code,{children:"U3"})," with ",(0,a.jsx)(t.code,{children:"C13"})," and ",(0,a.jsx)(t.code,{children:"C24"}),", is fitted as the fallback, but its output is isolated by the DNP link ",(0,a.jsx)(t.code,{children:"R104"}),". The regulator costs a few cents. Retrofitting a SOT-23-5 regulator and two 0603 capacitors onto a populated board costs far more, and risks the board."]}),"\n",(0,a.jsx)(t.h2,{id:"exactly-one-link-in-a-select-group",children:"Exactly one link in a select group"}),"\n",(0,a.jsx)(t.p,{children:"Where a rail can come from several sources, each source has its own link to the rail, and exactly one link is fitted. The schematic states that rule beside the links, so a technician never fits two and connects two supplies together."}),"\n",(0,a.jsx)(t.p,{children:"A select link that sits in series with another link is a trap. If enabling a source needs two links, fitting one of them does nothing, and nothing on the board says why. Wherever that happens, the schematic note says so, and so does the product's bring-up sheet."}),"\n",(0,a.jsx)(t.h2,{id:"a-resistor-in-the-select-position-measures-current",children:"A resistor in the select position measures current"}),"\n",(0,a.jsx)(t.p,{children:"On a prototype, a 1 \u03A9 1 % resistor in a select position turns the link into a current shunt. The voltage across it gives the rail current directly, with no break in the circuit. The production board fits 0 \u03A9 in the same land."}),"\n",(0,a.jsx)(t.h2,{id:"leave-a-land-for-a-value-not-yet-known",children:"Leave a land for a value not yet known"}),"\n",(0,a.jsx)(t.p,{children:"Where a part's correct value can only be found on the bench, the land is placed and the part is fitted at a neutral value or left DNP. A USB data line carries 0 \u03A9 in a land sized for a 22 \u03A9 series resistor, because the reference designs use 0 \u03A9 but a signal-integrity problem would need the resistor. A filter capacitor whose value is not yet proven is better left DNP than fitted at a value that does nothing."}),"\n",(0,a.jsx)(t.h2,{id:"why-this-is-planned-in-not-patched-on",children:"Why this is planned in, not patched on"}),"\n",(0,a.jsx)(t.p,{children:"A wired link, a bodge wire or a leaded part added on the bench is fragile, hides the real circuit from the next person, and can itself become the fault. On the first MDD500 board, a leaded 10 k\u03A9 resistor added to force a converter on simply fought a processor output that is designed to hold that converter off before firmware runs. Every isolation point a bring-up might need is therefore designed in as a DNP land before the board is ordered."}),"\n",(0,a.jsx)(t.h2,{id:"documenting-dnp-parts",children:"Documenting DNP parts"}),"\n",(0,a.jsx)(t.p,{children:'Every DNP part is documented in full, with its function and the condition under which it is fitted. Product pages mark it as "DNP - not fitted at launch" on first mention, and a DNP sub-circuit carries a "Not fitted at launch" notice at the top of its page.'})]})}function h(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},8453(e,t,i){i.d(t,{R:()=>o,x:()=>r});var n=i(6540);let a={},s=n.createContext(a);function o(e){let t=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);